def min_balloon_cost(cost_g: int, cost_p: int, participants: list[list[int]]) -> int:
    p1_solves = sum(p[0] for p in participants)
    p2_solves = sum(p[1] for p in participants)
    opt1 = p1_solves * cost_g + p2_solves * cost_p
    opt2 = p1_solves * cost_p + p2_solves * cost_g
    return min(opt1, opt2)
